        if (m->data[0] < FM_PATCHES) {
            all_off();
            select_patch(m->data[0]);
            sb_midi.program = m->data[0];
            again = 1;
        }
        break;
    case MIDI_BEND:
        /* 14 bits, 8192 the middle: +-bend_range semitones. */
        bend = ((s32)(m->data[0] | (u32)m->data[1] << 7) - 8192) * midi_settings.bend_range / 2;
