static void draw_keys(void)
{
    u32 k, pass;

    /* The black around and between the lower keys (since M5 only that,
     * not the whole strip first: the keys cover the rest). */
    gfx_fill(0, KEYS_Y, 8, LOWER_H, BLACK);
    gfx_fill(8 + 14 * 16 - 1, KEYS_Y, SCREEN_W - (8 + 14 * 16 - 1), LOWER_H, BLACK);
    for (k = 0; k < 15; k++)
        gfx_fill(8 + 14 * k + 13, KEYS_Y, 1, LOWER_H, BLACK);
    /* Lower keys first, then the raised keys over them. */
    for (pass = 0; pass < 2; pass++) {
        for (k = 0; k < 27; k++) {
            u32 s = key_shape[k], down = (u32)input_value(INPUT_KEY1 + k);
            int note = FM_KEY1_NOTE + (int)k + 12 * (s32)sb_audio.engine[SYNTH_OCTAVE];
            u32 midi = note >= 0 && note < 128 && (fm_midi_notes[note >> 5] >> (note & 31) & 1);
            if (!(s & 0x80) && !pass)
                gfx_fill(8 + 14 * s, KEYS_Y, 13, LOWER_H, down ? ORANGE : midi ? CYAN : WHITE);
            else if ((s & 0x80) && pass)
                gfx_fill(8 + 14 * ((s & 0x7F) + 1) - 5, KEYS_Y, 9, RAISED_H, down ? ORANGE : midi ? CYAN : GREY);
        }
    }
}

/* The event line: the last event or MIDI note, padded with spaces. */
static char line[41];

static void draw_line(void)
{
